\label{clm:circulant}
Let $a := (a_0, a_1, \ldots, a_{k-1}) \in \mathbb{F}^k$ denote the first column of $A$. Then for any $m \in \mathbb{F}^k$, $A \cdot m$ is the length $k$ coefficient vector of the polynomial
$a(x) \cdot m(x) \; (\bmod \; x^k-1) \in \mathbb{F}_{<k}[x]$.

Fix $k \in I$, the code $D_k$ is constructed as follows. Let $a=(a_1, a_2, \ldots, a_k) \in \{0,1\}^k$ be the indicator vector of $S_k \subseteq [k]$, that is, $a_i=1$ if and only if $i \in S_k$. Let $A$ be the binary $k \times k$ circulant matrix whose first column is $a$, and let $D_k$ be a double-circulant code with generator matrix  $G=\begin{pmatrix}
        I_k \\ A
    \end{pmatrix}$.

\label{lem:sidon_1}
Suppose that $C \subseteq \mathbb{F}_q^{2k}$ is a linear code with generator matrix of the form $G=\begin{pmatrix}
        I_k \\ A
    \end{pmatrix}$, where $A$ is a $k \times k$ matrix over $\mathbb{F}_q$. Then if $A$ is a $(d,b)$-design matrix, then $C$ has distance at least $\frac{d} {b}+1$. Moreover, if $A$ is circulant, and each row in $A$ has weight at most $r$, then $A$ is $(2,d')$-balanced for $d'=\min\{\frac {d} {b}+1, \frac{k} {r}\}$.

\label{lem:sidon_3}
Suppose that $C \subseteq \mathbb{F}_q^{2k}$ is a linear code with a generator matrix of the form $G=\begin{pmatrix}
        I_k \\ A
    \end{pmatrix}$, where $A$ is a $k \times k$ matrix over $\mathbb{F}_q$. Then if $A$ is a $(d,b)$-design matrix, then $C$  can be decoded from less than $\frac{d} {2b}$ errors in time $poly(k, \log q)$.

The decoding algorithm  for the code  $C$ is given in Figure \ref{fig:matrix_design_dec} below. For $i \in [k]$, let $S_i \subseteq [k]$ denote the support of the $i$-th column in $A$. 


\begin{figure}[h]
  \begin{boxedminipage}{\textwidth} \small \medskip \noindent
    $\;$

    \underline{\textbf{Decoding algorithm  for the matrix design code $C$:}}
\begin{itemize}
\item \textbf{INPUT:} A received word $w=(w_0, w_1) \in \mathbb{F}_q^{2k}$, where $w_0, w_1 \in \mathbb{F}_q^k$ 
\item \textbf{OUTPUT:}  A codeword $c \in C$ so that $\mathsf{dist}(w,c)< \frac{d} {2b}$, or $\bot$ if such a codeword does not exist

\end{itemize}

\begin{enumerate}
\item \label{step:matrix_design_syndrome} Let $y:=A\cdot w_0 -w_1 \in \mathbb{F}_q^k$.
\item \label{step:matrix_design_error}
Compute $z =(z_1, \ldots, z_k) \in \mathbb{F}_q^k$, where for $i =1, \ldots, k$,
$z_i = \mathrm{Majority}\{ y_j \mid j \in \mathrm{supp}(S_i)\}$.
\item  \label{step:matrix_design_codeword}
Let $c_0 = w_0 - z \in \mathbb{F}_q^k$ and $c=G \cdot c_0$. 
\item \label{step:matrix_design_output}
 If $\mathsf{dist}(w,c) < \frac{d} {2b}$ return $c$, otherwise return $\bot$. 
\end{enumerate}

  \medskip

  \end{boxedminipage}

\caption{Decoding algorithm for matrix design codes}
\label{fig:matrix_design_dec}
\end{figure}

The running time of the algorithm is clearly $\mathrm{poly}(k, \log q)$. To show correctness, let $w=(w_0, w_1) \in \mathbb{F}_q^{2k}$ be a received word, where $w_0, w_1 \in \mathbb{F}_q^k$, and let 
$c=(c_0, c_1) \in C$ be a codeword so that $\mathsf{dist}(c,w) < \frac{d} {2b}$, where $c_0, c_1 \in \mathbb{F}_q^k$. We shall show that the algorithm will output $c$.

To this end, it suffices to show that the string $z$ which the algorithm computes on Step \ref{step:matrix_design_error}  satisfies that $z = w_0-c_0$, as in this case the algorithm will clearly compute the correct codeword $c$ on Step \ref{step:matrix_design_codeword}.

Let $e=(e_0,e_1):=w-c \in \mathbb{F}_q^{2k}$, where $e_0, e_1 \in \mathbb{F}_q^k$, and note that $\mathrm{wt}(e) < \frac{d} {2b}$ by assumption that $\mathsf{dist}(c,w) < \frac{d} {2b}$. Moreover, we have that
$$y = A\cdot w_0 - w_1 = A \cdot (c_0 + e_0) - (c_1 + e_1) =A \cdot (c_0 + e_0) - (A \cdot c_0 + e_1)  =A\cdot e_0 -e_1.$$ 

We would like to show that $z=e_0=w_0-c_0$. 
To this end, fix $i \in [k]$, we shall show that $z_i = (e_0)_i$. Let $S := \bigcup_{\ell \in \mathrm{supp}(e_0)\setminus \{i\}} S_\ell$. Note that for any $j \in S_i$ so that $j \notin S \cup \mathrm{supp}(e_1)$, we have that  $y_j = (e_0)_i$. We shall show that the majority of $j \in S_i$ satisfy that  $j \notin S \cup \mathrm{supp}(e_1)$, and consequently $z_i = (e_0)_i$. 

To see the latter, note that since $A$ is a $(d,b)$-design matrix, we have that $|S_i| \geq d$. Moreover, 
$|S_\ell \cap S_i| \leq  b$ for any $\ell \neq i$, and so 
$$|S \cap S_i| \leq \sum_{\ell \in \mathrm{supp}(e_0)\setminus \{i\}} |S_\ell \cap S_i|  \leq \mathrm{wt}(e_0) \cdot b.$$ But this implies in turn that 
$$|(S \cup \mathrm{supp}(e_1))\cap S_i| \leq |S\cap S_i| + |\mathrm{supp}(e_1)| \leq 
\mathrm{wt}(e_0) \cdot b+ \mathrm{wt}(e_1) \leq  \mathrm{wt}(e) \cdot b< \frac{d} {2}.$$
So the majority of $j \in S_i$ satisfy that  $j \notin S \cup \mathrm{supp}(e_1)$, and so $z_i = (e_0)_i$.


\begin{flushright} $\blacksquare$
